// frontend/src/features/tickets/TicketCreate.jsx - Simplified & Attractive UI Version
// Aligned with minimal required fields: Title, Description, Priority, Status (default Open), Creator (auto), Assigned To (optional), Timestamps (auto)
import React, { useState } from "react";
import api from "../../api/axios"; // Adjust path if needed
import { useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";

const TicketCreate = () => {
  const [form, setForm] = useState({
    title: "",
    description: "",
    priority: "LOW",
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const user = useSelector((state) => state.auth.user); // Creator will be auto-set by backend

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const data = {
        title: form.title,
        description: form.description,
        priority: form.priority,
        status: "OPEN", // Default as per requirements
        // Assigned To: optional, left blank for new ticket
      };

      await api.post("/tickets/", data);

      navigate("/employee");
    } catch (err) {
      console.error("Ticket creation error:", err);
      setError(
        err.response?.data?.detail ||
          err.response?.data?.message ||
          "Failed to create ticket. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <h3 style={styles.title}>Create New Sanchar Ticket</h3>

      {error && <div style={styles.errorAlert}>{error}</div>}

      <form onSubmit={handleSubmit} style={styles.form}>
        <div style={styles.inputGroup}>
          <label style={styles.label}>Title *</label>
          <input
            type="text"
            name="title"
            style={styles.input}
            placeholder="Enter ticket title (e.g., Network Issue in Sanchar Node)"
            value={form.title}
            onChange={handleChange}
            required
          />
        </div>

        <div style={styles.inputGroup}>
          <label style={styles.label}>Description *</label>
          <textarea
            name="description"
            style={styles.textarea}
            rows="6"
            placeholder="Describe the issue in detail..."
            value={form.description}
            onChange={handleChange}
            required
          />
        </div>

        <div style={styles.inputGroup}>
          <label style={styles.label}>Priority</label>
          <select
            name="priority"
            style={styles.select}
            value={form.priority}
            onChange={handleChange}
          >
            <option value="LOW">Low</option>
            <option value="MEDIUM">Medium</option>
            <option value="HIGH">High</option>
          </select>
        </div>

        <button
          type="submit"
          style={{
            ...styles.submitButton,
            opacity: loading || !form.title || !form.description ? 0.7 : 1,
          }}
          disabled={loading || !form.title || !form.description}
        >
          {loading ? "Submitting..." : "Submit Ticket"}
        </button>
      </form>
    </div>
  );
};

// Clean, Modern Styles - Purple Theme Inspired by Sanchar Helpdesk PDF
const styles = {
  container: {
    padding: "40px 20px",
    maxWidth: "700px",
    margin: "0 auto",
    background: "linear-gradient(to bottom, #f9faff, #ffffff)",
    minHeight: "100vh",
    fontFamily: "Arial, sans-serif",
  },
  title: {
    fontSize: "32px",
    textAlign: "center",
    marginBottom: "40px",
    color: "#4527a0", // Purple accent from PDF
    fontWeight: "700",
  },
  errorAlert: {
    padding: "16px",
    background: "linear-gradient(135deg, #ff4d4f, #cf1322)",
    color: "#ffffff",
    borderRadius: "8px",
    marginBottom: "24px",
    textAlign: "center",
  },
  form: {
    background: "#ffffff",
    padding: "32px",
    borderRadius: "16px",
    boxShadow: "0 8px 24px rgba(0,0,0,0.1)",
  },
  inputGroup: {
    marginBottom: "24px",
  },
  label: {
    display: "block",
    fontSize: "16px",
    fontWeight: "600",
    color: "#1a1a1a",
    marginBottom: "8px",
  },
  input: {
    width: "100%",
    padding: "12px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
    transition: "border-color 0.2s",
    ":focus": {
      borderColor: "#4527a0",
      outline: "none",
    },
  },
  textarea: {
    width: "100%",
    padding: "12px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
    resize: "vertical",
    transition: "border-color 0.2s",
    ":focus": {
      borderColor: "#4527a0",
      outline: "none",
    },
  },
  select: {
    width: "100%",
    padding: "12px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
    background: "#ffffff",
    cursor: "pointer",
  },
  submitButton: {
    width: "100%",
    padding: "14px",
    background: "linear-gradient(135deg, #7c4dff, #4527a0)",
    color: "#ffffff",
    border: "none",
    borderRadius: "8px",
    fontSize: "18px",
    fontWeight: "600",
    cursor: "pointer",
    transition: "opacity 0.2s",
  },
};

export default TicketCreate;
